begin;
create function pg_temp.assert_true(value boolean,message text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'assertion failed: %',message; end if; end; $$;
insert into auth.users(id) values('28000800-0000-4000-8000-000000000001'),('28000800-0000-4000-8000-000000000002'),('28000800-0000-4000-8000-000000000003');
insert into public.user_roles(user_id,role) values('28000800-0000-4000-8000-000000000001','professional') on conflict do nothing;
insert into public.professional_student_relationships(professional_user_id,student_user_id,status) values('28000800-0000-4000-8000-000000000001','28000800-0000-4000-8000-000000000002','active');
insert into public.account_snapshots(user_id,revision,state_schema_version,payload) values('28000800-0000-4000-8000-000000000002',1,2,'{"profile":{"heightCm":176,"birthDate":"1992-10-10","startWeight":85,"goal":"lose_weight","experience":"intermediate","privateField":"secret"},"bodyweight":[{"d":"2026-10-10","w":85,"t":1791642974742},{"d":"2026-10-20","w":84,"t":1792506974742}],"bodyMeasurements":[{"date":"2026-10-10","values":{"chest":95},"notes":"Referência"}],"privateSetting":"secret"}');
set local role authenticated;
select set_config('request.jwt.claim.sub','28000800-0000-4000-8000-000000000001',true);
select pg_temp.assert_true((select profile->>'heightCm'='176' and profile->>'birthDate'='1992-10-10' and not profile ? 'privateField' and weight_history->0->>'weight_kg'='84' and jsonb_array_length(weight_history)=2 and measurements->0->'measurements_cm'->>'chest'='95' and measurements->0->>'note'='Referência' from public.professional_client_detail('28000800-0000-4000-8000-000000000002')),'legacy account exposes allowed profile fields and ordered body history');
select set_config('request.jwt.claim.sub','28000800-0000-4000-8000-000000000003',true);
select pg_temp.assert_true(not exists(select 1 from public.professional_client_detail('28000800-0000-4000-8000-000000000002')),'legacy data is hidden from an unlinked user');
reset role;
insert into public.account_preferences(user_id,preferences) values('28000800-0000-4000-8000-000000000002','{"profile":{"heightCm":180}}');
set local role authenticated;
select set_config('request.jwt.claim.sub','28000800-0000-4000-8000-000000000001',true);
select pg_temp.assert_true((select profile->>'heightCm'='180' and profile->>'birthDate' is null and weight_history='[]'::jsonb and measurements='[]'::jsonb from public.professional_client_detail('28000800-0000-4000-8000-000000000002')),'migrated data wins and cleared fields do not revive old snapshot values');
reset role;
update public.professional_student_relationships set status='revoked' where professional_user_id='28000800-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','28000800-0000-4000-8000-000000000001',true);
select pg_temp.assert_true(not exists(select 1 from public.professional_client_detail('28000800-0000-4000-8000-000000000002')),'revoked relationship cannot read either source');
rollback;
